create or replace function public.admin_review_moderation_history(p_review_id uuid) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ begin if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and is_admin=true) then raise exception 'ADMIN_REQUIRED'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select a.id,a.review_id,a.actor_user_id,a.previous_status,a.new_status,a.reason,a.created_at,p.email as actor_email from public.review_moderation_actions a left join public.profiles p on p.id=a.actor_user_id where a.review_id=p_review_id) x),'[]'::jsonb); end; $function$;
revoke execute on function public.admin_review_moderation_history(uuid) from anon,authenticated; grant execute on function public.admin_review_moderation_history(uuid) to authenticated;
